using System;using System.Linq;using UnityEngine;using UnityEditor;using LWS.TruckSports.Editor;
namespace LWS.TruckLogRolling.Editor {public static class LogPresentationAuthoring {
 public static void InstallTimber(Transform parent){const string folder=LogAuthoring.Folder;var source=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/"+folder+"/Art/Owned port timber log.fbx");if(source==null)throw new Exception("Owned port log required");var temporary=UnityEngine.Object.Instantiate(source);try{var filter=temporary.GetComponentsInChildren<MeshFilter>(true).First(f=>f.sharedMesh!=null);var original=filter.sharedMesh;var vertices=original.vertices.Select(v=>filter.transform.TransformPoint(v)).ToArray();var bounds=new Bounds(vertices[0],Vector3.zero);foreach(var v in vertices)bounds.Encapsulate(v);int axis=bounds.size.x>bounds.size.y&&bounds.size.x>bounds.size.z?0:bounds.size.y>bounds.size.z?1:2;var rotation=axis==0?Quaternion.Euler(0,-90,0):axis==1?Quaternion.Euler(90,0,0):Quaternion.identity;for(int i=0;i<vertices.Length;i++)vertices[i]=rotation*(vertices[i]-bounds.center);var rotated=new Bounds(vertices[0],Vector3.zero);foreach(var v in vertices)rotated.Encapsulate(v);var factor=new Vector3(6/rotated.size.x,6/rotated.size.y,22/rotated.size.z);for(int i=0;i<vertices.Length;i++)vertices[i]=Vector3.Scale(vertices[i],factor);var normals=original.normals.Select(v=>{var n=rotation*filter.transform.TransformDirection(v);return new Vector3(n.x/factor.x,n.y/factor.y,n.z/factor.z).normalized;}).ToArray();string path="Assets/"+folder+"/Models/Owned timber log baked in metres.asset";var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(mesh==null){mesh=new Mesh();AssetDatabase.CreateAsset(mesh,path);}mesh.Clear();mesh.vertices=vertices;mesh.normals=normals;mesh.uv=original.uv;mesh.subMeshCount=original.subMeshCount;for(int sub=0;sub<original.subMeshCount;sub++)mesh.SetTriangles(original.GetTriangles(sub),sub);mesh.RecalculateBounds();mesh.RecalculateTangents();mesh.UploadMeshData(false);EditorUtility.SetDirty(mesh);
 var bark=SportsEventAuthoring.Mat(folder,"Owned textured log bark",new Color(.74f,.64f,.47f),.2f);bark.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/"+folder+"/Art/Bark_A_Albedo.png");bark.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/"+folder+"/Art/Bark_A_Normal.png"));bark.EnableKeyword("_NORMALMAP");bark.SetFloat("_BumpScale",.65f);var end=SportsEventAuthoring.Mat(folder,"Owned visible timber endgrain",new Color(.82f,.63f,.39f),.18f);end.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>("Assets/"+folder+"/Art/Log_End_1.png");var materials=new Material[mesh.subMeshCount];for(int sub=0;sub<materials.Length;sub++){var indices=mesh.GetTriangles(sub);float longitudinal=0;foreach(int index in indices)longitudinal+=Mathf.Abs(normals[index].z);materials[sub]=indices.Length>0&&longitudinal/indices.Length>.7f?end:bark;}var g=new GameObject("Owned solid timber fitted to actual log hull");g.transform.SetParent(parent,false);g.AddComponent<MeshFilter>().sharedMesh=mesh;g.AddComponent<MeshRenderer>().sharedMaterials=materials;if(Vector3.Distance(mesh.bounds.size,new Vector3(6,6,22))>.01f||g.transform.localPosition.sqrMagnitude>.001f)throw new Exception("Visual timber must match metre-baked hull bounds");}finally{UnityEngine.Object.DestroyImmediate(temporary);}}
}}
